/* Belarusian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ivan": "God is gracious — Hebrew Yohanan", "Maryna": "A beloved feminine name.", "Aleksandr": "defender of men — Greek Alexandros", "Olga": "holy, blessed — Old Norse heilagr", "Dmitri": "of Demeter — Greek", "Natalya": "birthday (of Christ) — Latin natalis", "Lukashenko": "Family name of Alexander Lukashenko, president of Belarus.", "-vich patronymics": "Belarusian middle names use -vich for sons: Ivanovich.", "-vna patronymics": "Belarusian middle names use -vna for daughters: Ivanovna.", "-ski surnames": "Belarusian surnames in -ski mark noble or regional origin."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ivan';
console.log(lookup(q));

